        {capture $c_2}
          {=og_text(og_get($v_o, ['name']))}
        {/capture}
        {=og_include('compose/Inline.latte', ['children' => (string) $c_2])|noescape}
      {/capture}
      {=og_include('compose/Inline.latte', ['class' => 'flex items-center gap-2', 'children' => (string) $c_3])|noescape}
      {capture $c_4}
        {=og_text(og_tpl('{0} · {1}', [og_get($v_o, ['note']), og_money(og_get($v_o, ['price']), og_get($v_o, ['currency']))]))}
      {/capture}
      {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
    {/capture}
    {=og_include('compose/Label.latte', ['class' => 'flex items-center justify-between gap-4 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted', 'attrs' => og_attrs(['data-slot', 'dish-option']), 'children' => (string) $c_5])|noescape}
  {/foreach}
{/capture}
{=og_include('compose/Fieldset.latte', ['class' => 'flex flex-col gap-2', 'attrs' => og_attrs(['data-slot', 'sides']), 'children' => (string) $c_6])|noescape}
